import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_min_softmax_kernel(
    const float* conv_output,
    float* output,
    int B,
    int C,
    int D,
    int H,
    int W
) {
    const int b = blockIdx.x / (H * W);
    const int hw = blockIdx.x % (H * W);
    const int h = hw / W;
    const int w = hw % W;
    const int c = threadIdx.x;

    if (c >= C) return;

    // Compute min across depth dimension
    float min_val = INFINITY;
    for (int d = 0; d < D; ++d) {
        const int idx = b*C*D*H*W + c*D*H*W + d*H*W + h*W + w;
        min_val = min(min_val, conv_output[idx]);
    }

    // Shared memory for channel-wise values
    extern __shared__ float smem[];
    smem[c] = min_val;
    __syncthreads();

    // Compute softmax parameters
    float max_val = -INFINITY;
    for (int i = 0; i < C; ++i) {
        max_val = max(max_val, smem[i]);
    }

    float exp_sum = 0.0f;
    for (int i = 0; i < C; ++i) {
        exp_sum += expf(smem[i] - max_val);
    }

    // Write final result
    const int out_idx = b*C*H*W + c*H*W + h*W + w;
    output[out_idx] = expf(smem[c] - max_val) / exp_sum;
}

torch::Tensor fused_min_softmax_cuda(torch::Tensor conv_output) {
    const int B = conv_output.size(0);
    const int C = conv_output.size(1);
    const int D = conv_output.size(2);
    const int H = conv_output.size(3);
    const int W = conv_output.size(4);

    auto output = torch::empty({B, C, H, W}, conv_output.options());

    const int grid_size = B * H * W;
    const int block_size = C;
    const int shared_mem = C * sizeof(float);

    fused_min_softmax_kernel<<<grid_size, block_size, shared_mem>>>(
        conv_output.data_ptr<float>(),
        output.data_ptr<float>(),
        B, C, D, H, W
    );

    return output;
}
"""

fused_kernel_cpp = "torch::Tensor fused_min_softmax_cuda(torch::Tensor conv_output);"

fused_min_softmax = load_inline(
    name='fused_min_softmax',
    cpp_sources=fused_kernel_cpp,
    cuda_sources=fused_kernel_source,
    functions=['fused_min_softmax_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, dim):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv3d(in_channels, out_channels, kernel_size, padding=kernel_size//2)
        self.fused_op = fused_min_softmax

    def forward(self, x):
        x = self.conv(x)
        return self.fused_op.fused_min_softmax_cuda(x)
